import{rt as e,t,tt as n,xt as r}from"./chunks/framework.CuR1irRm.js";var i=JSON.parse(`{"title":"Kubernetes deployment limitations","description":"","frontmatter":{},"headers":[],"relativePath":"limitation/kubernetes-deployment.md","filePath":"limitation/kubernetes-deployment.md"}`),a={name:`limitation/kubernetes-deployment.md`};function o(t,i,a,o,s,c){return r(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1794138637000`},[...i[0]||=[e(`<h1 id="kubernetes-deployment-limitations" tabindex="-1">Kubernetes deployment limitations <a class="header-anchor" href="#kubernetes-deployment-limitations" aria-label="Permalink to “Kubernetes deployment limitations”">​</a></h1><p>Chart rendering and unit tests do not establish that deployments, upgrades, or identity boundaries are safe. Complete the following checks on the intended cluster and built images before deployment.</p><ul><li><strong>Authorization seeding:</strong> policy loads at startup. A pre-install/upgrade hook orders seeding before new workload resources but does not stop old pods or prevent concurrent policy writers. Follow the downtime-requiring external seed procedure in the <code>deploy/k8s/charts/authorization/README.md</code> for installs, upgrades, and rollbacks. On failed upgrades keep traffic blocked and controllers suspended until version-matched manual recovery; generic automatic rollback is unsafe. The chart cannot verify external seeding occurred. A future design must address rollout, rollback, and concurrency.</li><li><strong>Edge trust boundary:</strong> implement and independently verify a non-bypassable identity-header boundary and prevent direct downstream access. NetworkPolicy and acknowledgement flags alone are not proof. Follow the blockers in the <code>deploy/k8s/charts/notopia-edge/README.md</code>.</li><li><strong>Live identity tests:</strong> test direct edge access, alternate routes, spoofed-label pods, all five forged identity headers with anonymous and missing-claim tokens, and ordinary versus admin access. Test non-Istio mode separately if used; repeat after configuration or infrastructure changes.</li><li><strong>Live upgrades and gateway:</strong> exercise document and search-worker upgrades, hooks, rollout, gateway routing, and health exposure against running workloads on the intended implementation.</li><li><strong>Image and filesystem:</strong> test all six built service images and their migration/seed hooks with the configured UID, GID, filesystem mode, and actual startup dependencies and requests. The charts default to UID/GID 1000 and a read-only root, but these have not been validated against all images. Use writable volumes for required paths and verify ownership. Hook jobs do not expose extra volume mounts; hooks requiring them need a chart change. Root and a writable root filesystem are available for trusted debugging, but reduce isolation and do not persist container writes.</li><li><strong>Web cache:</strong> <code>.next/cache</code> is an ephemeral writable volume that masks image contents at that path. No explicit ISR configuration was found in the current web source. Verify the built image&#39;s runtime writes; ISR output can require writable paths outside that mount, including <code>.next/server</code>.</li><li><strong>Document scaling:</strong> see <a href="./document-replica-events.html">document replica event delivery</a>.</li></ul><p>For trusted debugging, each service chart accepts:</p><div class="language-yaml" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha" style="--shiki-light:#4c4f69;--shiki-dark:#cdd6f4;--shiki-light-bg:#eff1f5;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">podSecurityContext</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  runAsNonRoot</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> false</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  runAsUser</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 0</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  runAsGroup</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> 0</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">containerSecurityContext</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span></span>
<span class="line"><span style="--shiki-light:#1E66F5;--shiki-dark:#89B4FA;">  readOnlyRootFilesystem</span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">:</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> false</span></span></code></pre></div><p>These settings also apply to chart hooks. Cluster policy may reject root containers. The filesystem and process identity are independent; disabling either restriction does not disable the other.</p>`,6)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};